SELECT dbs.code as systemCode, dcid.id as detailId, dcid.next_level_id as nextLevelId, dcid.main_id as cfgInputId, dci.bill_type as billType FROM "dmp_cfg_input_detail" AS dcid INNER JOIN dmp_cfg_input AS dci ON dci.ID = dcid.main_id INNER JOIN dmp_basic_system AS dbs ON dbs.ID = dci.system_id WHERE dcid.is_deleted = FALSE AND dci.is_deleted = FALSE AND dbs.is_deleted = FALSE AND dci.bill_type IN
#{t}
AND dcid.next_level_id IN
#{nextLevelId}
AND dbs.code ILIKE ANY ( ARRAY
#{systemCode}
) GROUP BY dbs.code, dcid.id, dcid.next_level_id, dcid.main_id, dci.bill_type

select dcid.id AS id, dci.code as cfgInputCode, dci.name as name, dci.name as cfgInputName, dci.system_id as systemId, dbs.code as systemCode, dbs.name as systemName, dcid.create_time AS createTime, dcid.update_time AS updateTime, dcid.create_user_name AS createUserName, dcid.create_user_id AS createUserId, dcid.update_user_name AS updateUserName, dcid.update_user_id AS updateUserId, dcid.version AS version, dcid.is_deleted AS isDeleted, dcid.main_id AS mainId, dcid.next_level_id AS nextLevelId, dcid.last_time AS lastTime, dcid.next_time AS nextTime, dcid.interval_time AS intervalTime, dcid.override_time AS overrideTime, dcid.dealy_time AS dealyTime, dcid.max_interval_time AS maxIntervalTime, dcid.max_retry_count AS maxRetryCount, dcid.exec_timeout AS execTimeout, dcid.disabled AS disabled, dcid.task_type AS taskType, dcid.extend_json AS extendJson, dcid.remark from dmp_cfg_input_detail as dcid left join dmp_cfg_input dci on dci.id = dcid.main_id left join dmp_basic_system dbs on dbs.id = dci.system_id where ${params.sqlMap.default} and dcid.is_deleted = false
and dcid.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
dcid.create_time DESC

SELECT dcid.disabled AS tabFlag, CASE WHEN dcid.disabled = FALSE THEN '启用' ELSE '停用' END AS tabFlagName, count(*) AS count FROM dmp_cfg_input_detail WHERE dcid.is_deleted=FALSE
${params.permissionSql}
GROUP BY dcid.disabled
